"""Build the standalone HTML manual from this checkout's profile registry."""
from pathlib import Path
import argparse
import html
import re

root=Path(__file__).resolve().parents[2]
parser=argparse.ArgumentParser();parser.add_argument('--check',action='store_true');args=parser.parse_args()
registry=(root/'lib/dmm_protocols/dmm_protocols.cpp').read_text(encoding='utf-8')
profiles=re.findall(r'P\("([^"\n]+)",\s*"([^"\n]+)",\s*(\w+),\s*\w+,\s*(true|false),',registry)
assert len(profiles)==35
rows='\n'.join('<tr><td data-label="Profile ID"><code>'+html.escape(pid)+'</code></td><td data-label="Model(s)">'+html.escape(name)+'</td><td data-label="Family">'+html.escape(family)+'</td><td data-label="Upstream status">'+('Experimental' if experimental=='true' else 'Verified upstream')+'</td></tr>' for pid,name,family,experimental in profiles)

